(()=>{const cards=[...document.querySelectorAll("#services .animated-services .service")];if(!cards.length)return;const reduced=matchMedia("(prefers-reduced-motion:reduce)");function play(card){if(reduced.matches)return;card.classList.remove("playing");void card.offsetWidth;card.classList.add("playing")}const seen=new WeakSet;const observer=new IntersectionObserver(entries=>entries.forEach(e=>{e.target.dataset.visible=e.isIntersecting?"true":"false";if(e.isIntersecting&&!seen.has(e.target)){seen.add(e.target);play(e.target)}pause(e.target)}),{threshold:.2});function pause(card){card.querySelectorAll("*").forEach(el=>el.style.animationPlayState=document.hidden||card.dataset.visible==="false"?"paused":"")}cards.forEach(card=>observer.observe(card));document.addEventListener("visibilitychange",()=>{cards.forEach(pause);expire()});function expire(){document.querySelectorAll("#services [data-seasonal-offer]").forEach(el=>{if(Date.now()>=Date.parse(el.dataset.deadline))el.hidden=true})}expire();setInterval(expire,3e4)})();